import {
  useState
} from "react";

import api from "../api/axios";

const Signup = () => {

  const [formData,
    setFormData
  ] = useState({
    name:"",
    email:"",
    address:"",
    password:""
  });

  const handleChange =
  (e)=>{

    setFormData({
      ...formData,
      [e.target.name]:
      e.target.value
    });

  };

  const handleSubmit =
  async (e)=>{

    e.preventDefault();

    try{

      await api.post(
        "/auth/register",
        formData
      );

      alert(
        "Registration Successful"
      );

    }
    catch(error){

      alert(
        error.response?.data?.message
      );

    }

  };

  return(
    <div>

      <h2>Signup</h2>

      <form
        onSubmit={
          handleSubmit
        }
      >

        <input
          name="name"
          placeholder="Name"
          onChange={
            handleChange
          }
        />

        <br/><br/>

        <input
          name="email"
          placeholder="Email"
          onChange={
            handleChange
          }
        />

        <br/><br/>

        <input
          name="address"
          placeholder="Address"
          onChange={
            handleChange
          }
        />

        <br/><br/>

        <input
          type="password"
          name="password"
          placeholder="Password"
          onChange={
            handleChange
          }
        />

        <br/><br/>

        <button>
          Register
        </button>

      </form>

    </div>
  );
};

export default Signup;
